1. /**
2.  * Game configuration constants.
3.  */
4. 
5. export const GAME_WIDTH = 640;
6. export const GAME_HEIGHT = 528; // 480 map + 48 HUD message bar
7. export const TILE_SIZE = 32;
8. 
9. /**
10.  * Debug mode — toggled via the [debug mode] checkbox above the game canvas.
11.  * When enabled: shows a debug panel below the game with full action logs
12.  * and live state, prints to the browser console, and enables cheat keys
13.  * in battle (K = kill monster, H = full heal, P = restore MP,
14.  * G = +100 gold, L = level up, X = max XP).
15.  */
16. /** Returns true when running locally (not on a *.github.io deployment). */
17. export function isLocalDev(): boolean {
18.   const host = globalThis.location?.hostname ?? "localhost";
19.   return !host.endsWith(".github.io");
20. }
21. 
22. let _debug = false;
23. type DebugListener = (on: boolean) => void;
24. const _listeners: DebugListener[] = [];
25. 
26. export function isDebug(): boolean {
27.   return _debug;
28. }
29. export function toggleDebug(): boolean {
30.   _debug = !_debug;
31.   _listeners.forEach((fn) => fn(_debug));
32.   return _debug;
33. }
34. export function setDebug(on: boolean): void {
35.   if (_debug !== on) {
36.     _debug = on;
37.     _listeners.forEach((fn) => fn(_debug));
38.   }
39. }
40. export function onDebugChanged(fn: DebugListener): void {
41.   _listeners.push(fn);
42. }
43. export function offDebugChanged(fn: DebugListener): void {
44.   const idx = _listeners.indexOf(fn);
45.   if (idx >= 0) _listeners.splice(idx, 1);
46. }
47. export function debugLog(...args: unknown[]): void {
48.   if (_debug) console.log("[DEBUG]", ...args);
49. }
50. 
51. // --- HTML Debug Panel ---
52. 
53. /** Maximum number of log lines to keep in the debug panel. */
54. const MAX_DEBUG_LOG_LINES = 200;
55. 
56. /** Cached DOM element references for the debug panel (avoid re-querying every call). */
57. let _debugLogEl: HTMLElement | null | undefined;
58. let _debugStateEl: HTMLElement | null | undefined;
59. 
60. function getDebugLogEl(): HTMLElement | null {
61.   if (_debugLogEl === undefined) _debugLogEl = document.getElementById("debug-log");
62.   return _debugLogEl;
63. }
64. 
65. function getDebugStateEl(): HTMLElement | null {
66.   if (_debugStateEl === undefined) _debugStateEl = document.getElementById("debug-state");
67.   return _debugStateEl;
68. }
69. 
70. /** Append a message to the HTML debug log panel. */
71. export function debugPanelLog(msg: string, isDebugMsg = false, cssClass?: string): void {
72.   const el = getDebugLogEl();
73.   if (!el) return;
74.   // Remove previous spacer if present
75.   const oldSpacer = el.querySelector(".log-spacer");
76.   if (oldSpacer) oldSpacer.remove();
77.   // Add the log line
78.   const line = document.createElement("div");
79.   line.textContent = msg;
80.   if (cssClass) line.className = cssClass;
81.   else if (isDebugMsg) line.className = "debug-msg";
82.   el.appendChild(line);
83.   // Trim oldest lines if over limit
84.   const lines = el.querySelectorAll("div:not(.log-spacer)");
85.   if (lines.length > MAX_DEBUG_LOG_LINES) {
86.     const toRemove = lines.length - MAX_DEBUG_LOG_LINES;
87.     for (let i = 0; i < toRemove; i++) lines[i].remove();
88.   }
89.   // Add trailing spacer for readability
90.   const spacer = document.createElement("div");
91.   spacer.className = "log-spacer";
92.   el.appendChild(spacer);
93.   // Auto-scroll to bottom
94.   el.scrollTop = el.scrollHeight;
95. }
96. 
97. /** Update the live state bar in the HTML debug panel. */
98. export function debugPanelState(info: string): void {
99.   const el = getDebugStateEl();
100.   if (!el) return;
101.   el.textContent = info;
102. }
103. 
104. /** Clear the HTML debug log panel (e.g. when entering a new scene). */
105. export function debugPanelClear(): void {
106.   const el = getDebugLogEl();
107.   if (!el) return;
108.   el.innerHTML = "";
109. }
110. 
111. // --- Debug Command Input ---
