       Phaser.Cameras.Scene2D.Events.FADE_IN_COMPLETE,
       duration,
       "scene fade-in",
       () => this.restoreCamera(),
     );
     this.scene.cameras.main.fadeIn(
       duration,
       red,
       green,
       blue,
     );
   }

