118. async function exitHeroCutscene(page: Page, cutsceneId: string): Promise<void> {
119.   await holdKey(page, "Escape");
120.   if (cutsceneId === "campaign.twelvefoldCovenant.epilogue") {
121.     await waitForState(page, "ENDING | Choices");
122.     await holdKey(page, "Enter");
123.   }
