127. async function updateAccessibility(
128.   page: Page,
129.   controls: readonly string[],
130. ): Promise<void> {
131.   await holdKey(page, "Escape");
132.   await clickLayoutItem(page, "escape-menu-settings");
133.   for (const control of controls) {
134.     await clickLayoutItem(page, control);
135.   }
136.   await holdKey(page, "Escape");
137.   await expect(page.locator("#debug-state")).not.toContainText("[MENU]");
138. }
