140. test("every story path resolves the live hero visual and selected loadout", async ({
141.   page,
142. }) => {
143.   const browserErrors: string[] = [];
144.   page.on("pageerror", (error) => browserErrors.push(error.message));
145.   page.on("console", (message) => {
146.     if (message.type() === "error") browserErrors.push(message.text());
147.   });
148.   await page.addInitScript(() => {
149.     localStorage.clear();
150.     let seed = 0x2d0d;
151.     Math.random = () => {
152.       seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
153.       return seed / 0x1_0000_0000;
154.     };
155.   });
156.   await createCampaign(page);
157. 
158.   const fixtures = ["knightLight", "wizardDeep", "barbarianTan", "bardBlue"];
159.   const loadouts = ["unarmored", "plateShield", "robes", "dualWield", "lateGame"];
160.   for (const [index, cutsceneId] of getHeroCutsceneIds().entries()) {
161.     const fixture = fixtures[index % fixtures.length]!;
162.     const loadout = loadouts[index % loadouts.length]!;
163.     await launchHeroCutscene(page, cutsceneId, fixture, loadout);
164.     await exitHeroCutscene(page, cutsceneId);
165.   }
166. 
167.   expect(browserErrors).toEqual([]);
168. });
